class Solution:
    def countSubstrings(self, s: str) -> int:
        # freq[d] for d=1..9, index 0 unused
        freq = [None] + [[0]*d for d in range(1, 10)]
        ans = 0
        for ch in s:
            digit = ord(ch) - 48
            # update all freq arrays
            for d in range(1, 10):
                old = freq[d]
                new = [0] * d
                dm = digit % d
                for rem, cnt in enumerate(old):
                    if cnt:
                        new_rem = (rem * 10 + digit) % d
                        new[new_rem] += cnt
                new[dm] += 1
                freq[d] = new
            if digit != 0:
                ans += freq[digit][0]
        return ans

