from typing import List

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        n = len(nums)
        parent = list(range(n))
        size = [1] * n

        def find(x: int) -> int:
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(x: int, y: int) -> None:
            rx, ry = find(x), find(y)
            if rx == ry:
                return
            if size[rx] < size[ry]:
                parent[rx] = ry
                size[ry] += size[rx]
            else:
                parent[ry] = rx
                size[rx] += size[ry]

        # Map value to index for values <= threshold
        val_to_idx = {}
        for i, v in enumerate(nums):
            if v <= threshold:
                val_to_idx[v] = i

        # first_divisor[m] stores the index of the first element in nums that divides m
        first_divisor = [-1] * (threshold + 1)

        # For each present value, iterate its multiples
        for v, idx_v in val_to_idx.items():
            for m in range(v, threshold + 1, v):
                if first_divisor[m] != -1:
                    union(idx_v, first_divisor[m])
                else:
                    first_divisor[m] = idx_v

        # Count distinct roots
        roots = set()
        for i in range(n):
            roots.add(find(i))
        return len(roots)

